fetch("/api/status")
  .then(response => response.json())
  .then(status => { document.querySelector("#status").textContent = `Checkout ${status.version}`; });

document.querySelector("#pay-button").addEventListener("click", () => {
  const result = document.querySelector("#result");
  const method = document.querySelector("#method").value;
  const cart = { items: [{ price_cents: 1999, quantity: 1 }] };
  result.textContent = "Processing payment...";
  fetch("/api/checkout", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ cart, method }),
  })
    .then(response => response.json().then(body => ({ ok: response.ok, body })))
    .then(({ ok, body }) => {
      result.textContent = ok
        ? `Payment ${body.status}: $${(body.amount_cents / 100).toFixed(2)} via ${body.method}`
        : `Payment failed: ${body.error}`;
    })
    .catch(() => { result.textContent = "Payment failed: network error"; });
});

const CART = { items: [{ price_cents: 1999, quantity: 1 }] };

function setStatus(text) {
  document.querySelector("#status").textContent = text;
}

function setResult(text) {
  document.querySelector("#result").textContent = text;
}

fetch("/api/status")
  .then(response => response.json())
  .then(status => { setStatus(`Checkout ${status.version}`); })
  .catch(() => { setStatus("Checkout status unavailable"); });

const payButton = document.querySelector("#pay");

payButton.addEventListener("click", () => {
  payButton.disabled = true;
  setResult("");
  setStatus("Processing payment...");

  fetch("/api/checkout", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ cart: CART, method: "card" })
  })
    .then(async response => {
      const data = await response.json();
      if (!response.ok) {
        throw new Error(data.error || `Request failed (${response.status})`);
      }
      return data;
    })
    .then(result => {
      const amount = (result.amount_cents / 100).toFixed(2);
      setResult(`Payment ${result.status}: $${amount} via ${result.method}`);
      setStatus("Checkout complete");
    })
    .catch(error => {
      setResult(`Error: ${error.message}`);
      setStatus("Checkout failed");
    })
    .finally(() => {
      payButton.disabled = false;
    });
});

